#!/bin/bash
set -euo pipefail

export LC_ALL=C
mkdir -p /home/eval/data

awk -F '\t' '
    NR == 1 { next }
    {
        units[$1] += $3
        revenue[$1] += $3 * $4
    }
    END {
        for (region in units)
            printf "%s\t%d\t%.2f\n", region, units[region], revenue[region]
    }
' /home/eval/data/sales.tsv |
sort -t $'\t' -k3,3nr -k1,1 |
awk -F '\t' '
    BEGIN {
        printf "%-8s %6s %10s\n", "REGION", "UNITS", "REVENUE"
    }
    {
        printf "%-8s %6d %10.2f\n", $1, $2, $3
        total_units += $2
        total_revenue += $3
    }
    END {
        print "--------------------------"
        printf "%-8s %6d %10.2f\n", "TOTAL", total_units, total_revenue
    }
' > /home/eval/data/report.txt

exit 0
